                post_hook={
                    "sql": "create or replace table snitch_db.maplemonk.metafields_data as ( WITH master AS ( select sku_group,product_name,sellable_inventory,sku_class from snitch_db.maplemonk.availability_master_v2 ), live_date as ( select sku_group, status, FINAL_LIVE_DATE from snitch_db.maplemonk.product_journey ), id as ( select distinct SPLIT_PART(id, \'/\', -1) AS id, LEFT(value:sku::STRING, LENGTH(value:sku::STRING) - POSITION(\'-\' IN REVERSE(value:sku::STRING))) AS sku_group FROM snitch_db.maplemonk.new_meafields_product_products_graph_ql, LATERAL FLATTEN(input => PARSE_JSON(variants)) AS value ), product_type as ( SELECT distinct producttype as category, status, title, LEFT(value:sku::STRING, LENGTH(value:sku::STRING) - POSITION(\'-\' IN REVERSE(value:sku::STRING))) AS sku_group FROM snitch_db.maplemonk.new_meafields_product_products_graph_ql, LATERAL FLATTEN(input => PARSE_JSON(variants)) AS value ), occassion AS ( SELECT DISTINCT REPLACE(A.value:value, \'\"\', \'\') AS occassion, LEFT(B.value:sku::STRING, LENGTH(B.value:sku::STRING) - POSITION(\'-\' IN REVERSE(B.value:sku::STRING))) AS sku_group FROM snitch_db.maplemonk.new_meafields_product_products_graph_ql, LATERAL FLATTEN(input => metafields) A, LATERAL FLATTEN(input => PARSE_JSON(variants)) B WHERE REPLACE(A.value:key, \'\"\', \'\') = \'occassion_new\' ), model as ( SELECT DISTINCT replace(REPLACE(A.value:value, \'\"\', \'\'),\'Model-\',\'\') AS model, LEFT(B.value:sku::STRING, LENGTH(B.value:sku::STRING) - POSITION(\'-\' IN REVERSE(B.value:sku::STRING))) AS sku_group FROM snitch_db.maplemonk.new_meafields_product_products_graph_ql, LATERAL FLATTEN(input => metafields) A, LATERAL FLATTEN(input => PARSE_JSON(variants)) B WHERE REPLACE(A.value:key, \'\"\', \'\') = \'model\' ), designer as ( SELECT DISTINCT REPLACE(A.value:value, \'\"\', \'\') AS designer, LEFT(B.value:sku::STRING, LENGTH(B.value:sku::STRING) - POSITION(\'-\' IN REVERSE(B.value:sku::STRING))) AS sku_group FROM snitch_db.maplemonk.new_meafields_product_products_graph_ql, LATERAL FLATTEN(input => metafields) A, LATERAL FLATTEN(input => PARSE_JSON(variants)) B WHERE REPLACE(A.value:key, \'\"\', \'\') = \'designer\' ), print_design AS ( SELECT DISTINCT REPLACE(A.value:value, \'\"\', \'\') AS print_design, LEFT(B.value:sku::STRING, LENGTH(B.value:sku::STRING) - POSITION(\'-\' IN REVERSE(B.value:sku::STRING))) AS sku_group FROM snitch_db.maplemonk.new_meafields_product_products_graph_ql, LATERAL FLATTEN(input => metafields) A, LATERAL FLATTEN(input => PARSE_JSON(variants)) B WHERE REPLACE(A.value:key, \'\"\', \'\') = \'print_design\' ), collar AS ( SELECT DISTINCT REPLACE(A.value:value, \'\"\', \'\') AS collar, LEFT(B.value:sku::STRING, LENGTH(B.value:sku::STRING) - POSITION(\'-\' IN REVERSE(B.value:sku::STRING))) AS sku_group FROM snitch_db.maplemonk.new_meafields_product_products_graph_ql, LATERAL FLATTEN(input => metafields) A, LATERAL FLATTEN(input => PARSE_JSON(variants)) B WHERE REPLACE(A.value:key, \'\"\', \'\') = \'collar\' ), material AS ( SELECT DISTINCT REPLACE(A.value:value, \'\"\', \'\') AS material, LEFT(B.value:sku::STRING, LENGTH(B.value:sku::STRING) - POSITION(\'-\' IN REVERSE(B.value:sku::STRING))) AS sku_group FROM snitch_db.maplemonk.new_meafields_product_products_graph_ql, LATERAL FLATTEN(input => metafields) A, LATERAL FLATTEN(input => PARSE_JSON(variants)) B WHERE REPLACE(A.value:key, \'\"\', \'\') = \'material\' ), sleeves_type AS ( SELECT DISTINCT REPLACE(A.value:value, \'\"\', \'\') AS sleeves_type, LEFT(B.value:sku::STRING, LENGTH(B.value:sku::STRING) - POSITION(\'-\' IN REVERSE(B.value:sku::STRING))) AS sku_group FROM snitch_db.maplemonk.new_meafields_product_products_graph_ql, LATERAL FLATTEN(input => metafields) A, LATERAL FLATTEN(input => PARSE_JSON(variants)) B WHERE REPLACE(A.value:key, \'\"\', \'\') = \'sleeves_type\' ), fit AS ( SELECT DISTINCT REPLACE(A.value:value, \'\"\', \'\') AS fit, LEFT(B.value:sku::STRING, LENGTH(B.value:sku::STRING) - POSITION(\'-\' IN REVERSE(B.value:sku::STRING))) AS sku_group FROM snitch_db.maplemonk.new_meafields_product_products_graph_ql, LATERAL FLATTEN(input => metafields) A, LATERAL FLATTEN(input => PARSE_JSON(variants)) B WHERE REPLACE(A.value:key, \'\"\', \'\') = \'fit\' ), color AS ( SELECT DISTINCT REPLACE(REPLACE(REPLACE(A.value:values, \'[\', \'\'), \']\', \'\'), \'\"\', \'\') AS color, LEFT(B.value:sku::STRING, LENGTH(B.value:sku::STRING) - POSITION(\'-\' IN REVERSE(B.value:sku::STRING))) AS sku_group FROM snitch_db.maplemonk.new_meafields_product_products_graph_ql, LATERAL FLATTEN (input => options) A, LATERAL FLATTEN(input => PARSE_JSON(variants)) B WHERE REPLACE(A.value:position, \'\"\', \'\') = 1 ), style AS ( SELECT DISTINCT REPLACE(A.value:value, \'\"\', \'\') AS style, LEFT(B.value:sku::STRING, LENGTH(B.value:sku::STRING) - POSITION(\'-\' IN REVERSE(B.value:sku::STRING))) AS sku_group FROM snitch_db.maplemonk.new_meafields_product_products_graph_ql, LATERAL FLATTEN(input => metafields) A, LATERAL FLATTEN(input => PARSE_JSON(variants)) B WHERE REPLACE(A.value:key, \'\"\', \'\') = \'style\' ), closure AS ( SELECT DISTINCT REPLACE(A.value:value, \'\"\', \'\') AS closure, LEFT(B.value:sku::STRING, LENGTH(B.value:sku::STRING) - POSITION(\'-\' IN REVERSE(B.value:sku::STRING))) AS sku_group FROM snitch_db.maplemonk.new_meafields_product_products_graph_ql, LATERAL FLATTEN(input => metafields) A, LATERAL FLATTEN(input => PARSE_JSON(variants)) B WHERE REPLACE(A.value:key, \'\"\', \'\') = \'closure\' ), length AS ( SELECT DISTINCT REPLACE(A.value:value, \'\"\', \'\') AS length, LEFT(B.value:sku::STRING, LENGTH(B.value:sku::STRING) - POSITION(\'-\' IN REVERSE(B.value:sku::STRING))) AS sku_group FROM snitch_db.maplemonk.new_meafields_product_products_graph_ql, LATERAL FLATTEN(input => metafields) A, LATERAL FLATTEN(input => PARSE_JSON(variants)) B WHERE REPLACE(A.value:key, \'\"\', \'\') = \'length\' ), vendor AS ( SELECT DISTINCT REPLACE(A.value:value, \'\"\', \'\') AS vendor, LEFT(B.value:sku::STRING, LENGTH(B.value:sku::STRING) - POSITION(\'-\' IN REVERSE(B.value:sku::STRING))) AS sku_group FROM snitch_db.maplemonk.new_meafields_product_products_graph_ql, LATERAL FLATTEN(input => metafields) A, LATERAL FLATTEN(input => PARSE_JSON(variants)) B WHERE REPLACE(A.value:key, \'\"\', \'\') = \'vendor\' ), rise AS ( SELECT DISTINCT REPLACE(A.value:value, \'\"\', \'\') AS rise, LEFT(B.value:sku::STRING, LENGTH(B.value:sku::STRING) - POSITION(\'-\' IN REVERSE(B.value:sku::STRING))) AS sku_group FROM snitch_db.maplemonk.new_meafields_product_products_graph_ql, LATERAL FLATTEN(input => metafields) A, LATERAL FLATTEN(input => PARSE_JSON(variants)) B WHERE REPLACE(A.value:key, \'\"\', \'\') = \'rise\' ), pocket AS ( SELECT DISTINCT REPLACE(A.value:value, \'\"\', \'\') AS pocket, LEFT(B.value:sku::STRING, LENGTH(B.value:sku::STRING) - POSITION(\'-\' IN REVERSE(B.value:sku::STRING))) AS sku_group FROM snitch_db.maplemonk.new_meafields_product_products_graph_ql, LATERAL FLATTEN(input => metafields) A, LATERAL FLATTEN(input => PARSE_JSON(variants)) B WHERE REPLACE(A.value:key, \'\"\', \'\') = \'pocket\' ), product_tags as ( select distinct LEFT(value:sku::STRING, LENGTH(value:sku::STRING) - POSITION(\'-\' IN REVERSE(value:sku::STRING))) AS sku_group, tags as product_tags FROM snitch_db.maplemonk.new_meafields_product_products_graph_ql, LATERAL FLATTEN(input => PARSE_JSON(variants)) AS value ), duplicate_check as ( SELECT master.*, product_type.category as category, id.id, product_type.status as status, product_type.title, occassion.occassion AS occassion, print_design.print_design AS print_design, collar.collar AS collar, material.material AS material, sleeves_type.sleeves_type AS sleeve_type, fit.fit AS fit, style.style as style, color.color AS color, closure.closure as closure, length.length as length, vendor.vendor as vendor, pocket.pocket as pocket, rise.rise as rise, model.model as model, designer.designer as designer, ptag.product_tags as product_tags, case when lower(print_design) like \'%checks%\' then \'Checks\' when lower(print_design) like \'%animal%\' then \'Animal Print\' when lower(print_design) like \'%embroid%\' then \'Embroided\' when lower(print_design) like \'%floral%\' then \'Floral\' when lower(print_design) like \'%graphic%\' then \'Graphic Print\' when lower(print_design) like \'%embellished%\' then \'Embellished\' when lower(print_design) like \'%plain%\' then \'Solid\' when lower(print_design) like \'%solid%\' then \'Solid\' when lower(print_design) like \'%printed%\' then \'Printed\' when lower(print_design) like \'%self%\' then \'Self Design\' when lower(print_design) like \'%stripe%\' then \'Stripes\' when lower(print_design) like \'%crochet%\' then \'Crochet\' when lower(print_design) like \'%polka%\' then \'Polka Dots\' when lower(print_design) like \'%geometric%\' then \'Geometric\' when lower(print_design) like \'%stripe%\' then \'Stripes\' when lower(print_design) like \'%tie &%\' then \'Tie & Dye\' when lower(print_design) like \'%textured%\' then \'Textured\' Else \'Others\' END as Designs, case when lower(collar) like \'%cuban%\' then \'Cuban\' when lower(collar) like \'%crew%\' then \'Round\' when lower(collar) like \'%round%\' then \'Round\' when lower(collar) like \'%polo%\' then \'Polo\' when lower(collar) like \'%high neck%\' then \'High Neck\' when lower(collar) like \'%spread%\' then \'Spread\' when lower(collar) like \'%button down%\' then \'Button Down\' when lower(collar) like \'%mandarin%\' then \'Mandarin\' when lower(collar) like \'%baseball%\' then \'Baseball\' when lower(collar) like \'%classic%\' then \'Classic\' when lower(collar) like \'%shawl%\' then \'Shawl\' when lower(collar) like \'%hooded%\' then \'Hooded\' when lower(collar) like \'%mock%\' then \'Round\' when lower(collar) like \'%turtleneck%\' then \'Turtle Neck\' when lower(collar) like \'%camp%\' then \'Cuban\' Else \'Others\' END as Collar_New, case when lower(material) like \'%cotton%\' then \'Cotton\' when lower(material) like \'%poly%\' then \'Polyester\' when lower(material) like \'%rayon%\' then \'Rayon\' when lower(material) like \'%linen%\' then \'Linen\' when lower(material) like \'%terry%\' then \'Terry\' when lower(material) like \'%Cotton Poly%\' then \'Cotton\' when lower(material) like \'%modal%\' then \'Modal\' when lower(material) like \'%tencel%\' then \'Tencel\' when lower(material) like \'%nylon%\' then \'Nylon\' when lower(material) like \'%tencil%\' then \'Tencil\' when lower(material) like \'%steel%\' then \'Stainless Steel\' Else \'Others\' END as Material_New, case when lower(occassion) like \'%casual%\' then \'Casual Wear\' when lower(occassion) like \'%formal%\' then \'Formal Wear\' when lower(occassion) like \'%club%\' then \'Club Wear\' when lower(occassion) like \'%festive%\' then \'Festive Wear\' when lower(occassion) like \'%elevated%\' then \'Elevated\' when lower(occassion) like \'%intimate%\' then \'Intimate\' when lower(occassion) like \'%sleep%\' then \'Sleep and Lounge Wear\' when lower(occassion) like \'%athletic%\' then \'Athletic\' when lower(occassion) like \'%college%\' then \'College Wear\' when lower(occassion) like \'%street%\' then \'Street Wear\' Else \'Others\' END as occassion_New, case when category is null then 0 else 1 end as product_type_fill_rate, case when occassion is null then 0 else 1 end as occassion_fill_rate, case when PRINT_DESIGN is null then 0 else 1 end as PRINT_DESIGN_fill_rate, case when COLLAR is null then 0 else 1 end as COLLAR_fill_rate, case when MATERIAL is null then 0 else 1 end as MATERIAL_fill_rate, case when SLEEVE_TYPE is null then 0 else 1 end as SLEEVE_TYPE_fill_rate, case when FIT is null then 0 else 1 end as FIT_fill_rate, case when style is null then 0 else 1 end as style_fill_rate, case when color is null then 0 else 1 end as color_fill_rate, case when closure is null then 0 else 1 end as closure_fill_rate, case when length is null then 0 else 1 end as length_fill_rate, case when designs is null then 0 else 1 end as designs_fill_rate, case when collar_new is null then 0 else 1 end as collar_new_fill_rate, case when material_new is null then 0 else 1 end as material_new_fill_rate, case when occassion_new is null then 0 else 1 end as occassion_new_fill_rate, case when pocket is null then 0 else 1 end as pocket_fill_rate, case when rise is null then 0 else 1 end as rise_fill_rate, FROM master LEFT JOIN product_type ON master.sku_group = product_type.sku_group LEFT JOIN occassion ON master.sku_group = occassion.sku_group LEFT JOIN print_design ON master.sku_group = print_design.sku_group LEFT JOIN collar ON master.sku_group = collar.sku_group LEFT JOIN material ON master.sku_group = material.sku_group LEFT JOIN sleeves_type ON master.sku_group = sleeves_type.sku_group LEFT JOIN fit ON master.sku_group = fit.sku_group LEFT JOIN style on master.sku_group = style.sku_group LEFT JOIN color ON master.sku_group = color.sku_group LEFT JOIN closure ON master.sku_group = closure.sku_group LEFT JOIN rise ON master.sku_group = rise.sku_group LEFT JOIN pocket ON master.sku_group = pocket.sku_group LEFT JOIN model ON master.sku_group = model.sku_group LEFT JOIN designer ON master.sku_group = designer.sku_group LEFT JOIN product_tags ptag on master.sku_group = ptag.sku_group LEFT JOIN length ON master.sku_group = length.sku_group left join live_date on master.sku_group = live_date.sku_group left join vendor on master.sku_group = vendor.sku_group left join id on master.sku_group = id.sku_group ) select * from duplicate_check qualify row_number() over (partition by sku_group order by product_tags desc ) = 1 ); create or replace table snitch_db.maplemonk.metafields_fill_rate as ( select sku_group, category, sum(sellable_inventory) as inventory, case when category in (\'Joggers & Trackpants\',\'Denim\',\'Cargo Pants\',\'Boxers\',\'Night Suit & Pyjamas\',\'Trousers\',\'Chinos\',\'Shorts\',\'Inner Wear\',\'Jeans\') then sum(color_fill_rate+MATERIAL_fill_rate+FIT_fill_rate+occassion_fill_rate+style_fill_rate+product_type_fill_rate+closure_fill_rate+length_fill_rate+PRINT_DESIGN_fill_rate)/9 when category in (\'Shirts\',\'Shirt\',\'Kurta\',\'Overshirt\',\'Hoodies\',\'Sweaters\',\'T-Shirts\',\'Co-ords\',\'Sweatshirts\',\'Jackets\',\'Blazers\') then sum(color_fill_rate+MATERIAL_fill_rate+COLLAR_fill_rate+FIT_fill_rate+occassion_fill_rate+style_fill_rate+SLEEVE_TYPE_fill_rate+product_type_fill_rate+PRINT_DESIGN_fill_rate)/9 when category in (\'Accessories\',\'Sunglasses\',\'Shoes\',\'Perfumes\',\'Bags\',\'Belts\') then sum(color_fill_rate+MATERIAL_fill_rate+style_fill_rate+occassion_fill_rate+product_type_fill_rate)/5 end as fill_rate, case when category in (\'Joggers & Trackpants\',\'Denim\',\'Cargo Pants\',\'Boxers\',\'Night Suit & Pyjamas\',\'Trousers\',\'Chinos\',\'Shorts\',\'Inner Wear\',\'Jeans\') then sum(color_fill_rate+MATERIAL_fill_rate+FIT_fill_rate+occassion_fill_rate+style_fill_rate+product_type_fill_rate+closure_fill_rate+length_fill_rate+PRINT_DESIGN_fill_rate) when category in (\'Shirts\',\'Shirt\',\'Kurta\',\'Overshirt\',\'Hoodies\',\'Sweaters\',\'T-Shirts\',\'Co-ords\',\'Sweatshirts\',\'Jackets\',\'Blazers\') then sum(color_fill_rate+MATERIAL_fill_rate+COLLAR_fill_rate+FIT_fill_rate+occassion_fill_rate+style_fill_rate+SLEEVE_TYPE_fill_rate+product_type_fill_rate+PRINT_DESIGN_fill_rate) when category in (\'Accessories\',\'Sunglasses\',\'Shoes\',\'Perfumes\',\'Bags\',\'Belts\') then sum(color_fill_rate+MATERIAL_fill_rate+occassion_fill_rate+style_fill_rate+product_type_fill_rate) end as filled_metafields, from snitch_db.maplemonk.metafields_data group by 1,2 )",
                    "transaction": true
